<script setup lang="ts">
import { reactive, ref, onMounted, computed } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import DataTable from './DataTable.vue'
import { api, lines } from './api'
const route=useRoute(),router=useRouter(),edit=Boolean(route.params.id),error=ref(''),busy=ref(false),loading=ref(edit)
const form=reactive({name:'',description:'',targets:'',ports:'',urls:'',credential_ids:[] as string[],password_spray:false,credential_endpoints:'',screenshots:false,timeout:120})
const count=computed(()=>lines(form.targets).reduce((n,t)=>{const parts=t.split('/');if(parts.length===1)return n+1;const bits=t.includes(':')?128:32;const prefix=Number(parts[1]);return n+(Number.isInteger(prefix)&&prefix>=0&&prefix<=bits?2**(bits-prefix):0)},0))
onMounted(async()=>{if(edit)try{const scan=await api(`/scans/${route.params.id}`);Object.assign(form,scan.config,{targets:scan.config.targets.join('\n'),urls:scan.config.urls.join('\n'),credential_endpoints:scan.config.credential_endpoints.join('\n')})}catch(e){error.value=(e as Error).message}finally{loading.value=false}})
async function save(){busy.value=true;error.value='';try{if(!lines(form.targets).length&&!lines(form.urls).length)throw new Error('Provide at least one IP/CIDR target or HTTP(S) URL');const body={...form,targets:lines(form.targets),urls:lines(form.urls),credential_endpoints:lines(form.credential_endpoints)};const data=await api(edit?`/scans/${route.params.id}`:'/scans',edit?'PATCH':'POST',body);await router.push(`/scans/${data.id}`)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function select(id:string,checked:boolean){form.credential_ids=checked?[...form.credential_ids,id]:form.credential_ids.filter(x=>x!==id)}
</script>
<template><div class="page-heading"><div><p class="eyebrow">SCAN CONFIGURATION</p><h1>{{edit?'Edit scan':'New scan'}}</h1><p class="muted">Changes apply to future runs. Existing run snapshots are preserved.</p></div><RouterLink class="button subtle" to="/scans">Back to scans</RouterLink></div><p v-if="loading" role="status">Loading configuration…</p><form v-else @submit.prevent="save" class="scan-form"><section class="panel"><h2>Scope & discovery</h2><label>Scan name<input v-model="form.name" required maxlength="200" placeholder="Office network"></label><label>Description<textarea v-model="form.description" rows="2" maxlength="5000"/></label><div class="form-grid"><label>Authorized IP addresses / CIDRs<textarea v-model="form.targets" rows="5" placeholder="192.0.2.10&#10;2001:db8::/126"/><small>Optional when URLs are provided. One entry per line. {{count.toLocaleString()}} explicit addresses; administrator limits apply.</small></label><div><label>TCP ports<input v-model="form.ports" placeholder="22,80,443,8000-8100"><small>Default: 1–1024. No UDP scanning in the MVP.</small></label><label>Scanner timeout (seconds)<input v-model.number="form.timeout" type="number" min="5" max="600" required></label></div></div><label>Explicit HTTP(S) URLs<textarea v-model="form.urls" rows="3" placeholder="https://service.example.test/"/><small>Provide URLs, IP targets, or both. With URLs only, IPs are resolved and fixed at launch. When IP targets are supplied, URL destinations must belong to that scope.</small></label></section><section class="panel"><h2>Optional modules</h2><label class="check"><input v-model="form.screenshots" type="checkbox">Capture screenshots with EyeWitness</label><label class="check"><input v-model="form.password_spray" type="checkbox">Enable bounded credential validation</label><p class="muted">Both modules are off by default. Only HTTP Basic authentication is supported. Attempts use approved pairs, password first, with account and service budgets.</p><label v-if="form.password_spray">Explicitly approved credential endpoints<textarea v-model="form.credential_endpoints" rows="3" placeholder="https://service.example.test/protected" required/><small>Must also appear in the explicit URL list. Redirects are never followed for authentication.</small></label><h3>Approved credential library entries</h3><p>{{form.credential_ids.length}} selected (maximum 10)</p><DataTable endpoint="/credentials" query-key="credential-picker" :columns="[{key:'selected',label:'Select'},{key:'label',label:'Label'},{key:'username',label:'Username'}]"><template #selected="{row}"><input type="checkbox" :aria-label="`Select ${row.label}`" :checked="form.credential_ids.includes(row.id)" @change="select(row.id,($event.target as HTMLInputElement).checked)"></template></DataTable></section><p v-if="error" class="error" role="alert">{{error}}</p><div class="actions"><button :disabled="busy">{{busy?'Saving…':'Save scan'}}</button><RouterLink class="button subtle" to="/scans">Cancel</RouterLink></div></form></template>
